CREATE TYPE "letter_status" AS ENUM('pending', 'approved', 'declined');--> statement-breakpoint
CREATE TABLE "letters" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "letters_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"message" text NOT NULL,
	"sender_email" text NOT NULL,
	"status" "letter_status" DEFAULT 'pending'::"letter_status" NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
